'use strict';
let Q=[],session=null,tick=null;
const modules=['','Castellano','Navegación y Madrid','Accesibilidad y servicio','Normativa VTC'];
const desc=['','Gramática, vocabulario y comprensión.','GPS, destinos, calles y medio ambiente.','Atención, discapacidad y primeros auxilios.','Requisitos, autorizaciones y transporte.'];
const thresholds=[0,6,9,9,6],sizes=[0,12,18,18,12];
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let store;try{store=JSON.parse(localStorage.getItem('vtc-study-v1'))||{}}catch{store={}};
store.stats||={};store.bookmarks||=[];store.history||=[];
function save(){try{localStorage.setItem('vtc-study-v1',JSON.stringify(store))}catch{}}
function set(html){$('app').innerHTML=html;window.scrollTo(0,0)}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function flagged(q){return /distintivo.*(luna|medida|imagen)|antigüedad|etiqueta ambiental|distintivo ambiental|normativa.*flexibilizado|epistaxis|sede central del Ayuntamiento|Ballet Nacional|Aunque la calle|prete.?rir|preterir/i.test(q.question)}
function home(){clearInterval(tick);session=null;let st=Object.values(store.stats),n=st.reduce((a,x)=>a+x.tries,0),c=st.reduce((a,x)=>a+x.right,0),wrong=Q.filter(q=>store.stats[q.id]?.last===false).length;set(`<section class="hero"><div><span class="badge">TU RUTA AL PERMISO DE CONDUCTOR</span><h1>Un paso más cerca.<br>Una pregunta cada vez.</h1><p>Entrena con los cuatro modelos oficiales de Madrid. Practica a tu ritmo, descubre tus errores y comprueba cómo llevas cada bloque.</p><div class="actions"><button class="primary" onclick="start('practice')">Practicar 10 preguntas →</button>${store.active?'<button onclick="resume()">Continuar sesión</button>':''}</div></div><aside class="exam"><span class="eyebrow" style="color:#d6f09c">EL ENSAYO GENERAL</span><h2>Simulacro de examen</h2><p>60 preguntas · 60 minutos<br>12 + 18 + 18 + 12 por bloque.<br>Necesitas un 50 % en cada módulo.</p><button class="primary" onclick="start('exam')">Comenzar simulacro →</button><p class="subtle">La nota se muestra al finalizar.</p></aside></section><section class="stats"><div class="stat"><strong>${Q.length}</strong><span>preguntas sin duplicados exactos</span></div><div class="stat"><strong>${st.length}</strong><span>preguntas practicadas</span></div><div class="stat"><strong>${n?Math.round(c/n*100):0}%</strong><span>aciertos acumulados</span></div></section><div class="row"><h2>Elige tu siguiente bloque</h2><span class="subtle">Entrenamiento de 10 preguntas</span></div><section class="grid">${modules.slice(1).map((m,i)=>{let k=i+1,pool=Q.filter(q=>q.module===k),seen=pool.filter(q=>store.stats[q.id]).length;return `<article class="card"><span class="num">MÓDULO 0${k} · ${pool.length} PREGUNTAS</span><h3>${m}</h3><p>${desc[k]}</p><div class="row"><span class="subtle">${seen} de ${pool.length} practicadas</span><button onclick="start('practice',${k})">Practicar →</button></div></article>`}).join('')}</section><div class="actions"><button onclick="start('errors')" ${wrong?'':'disabled'}>Repasar errores (${wrong})</button><button onclick="start('bookmarks')" ${store.bookmarks.length?'':'disabled'}>Guardadas (${store.bookmarks.length})</button><button onclick="history()">Mis simulacros</button></div><div class="notice">Material de práctica independiente. Las soluciones se reproducen según los PDF, que pueden contener erratas o referencias normativas antiguas. Las preguntas señaladas requieren contraste con normativa vigente.</div>`)}
function start(mode,module=0){let pool=Q.filter(q=>!module||q.module===module);if(mode==='errors')pool=pool.filter(q=>store.stats[q.id]?.last===false);if(mode==='bookmarks')pool=pool.filter(q=>store.bookmarks.includes(q.id));let ids=mode==='exam'?[1,2,3,4].flatMap(m=>shuffle(Q.filter(q=>q.module===m)).slice(0,sizes[m]).map(q=>q.id)):shuffle(pool).slice(0,mode==='practice'?10:pool.length).map(q=>q.id);if(!ids.length)return;session={mode,ids,index:0,answers:{},checked:{},deadline:mode==='exam'?Date.now()+3600000:null};persist();renderQuestion()}
function persist(){store.active=session;save()}
function resume(){session=store.active;if(!session)return home();renderQuestion()}
function timer(){if(!session?.deadline)return;let left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));if($('clock'))$('clock').textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(!left)finish()}
function renderQuestion(){clearInterval(tick);if(!session)return;let q=Q.find(x=>x.id===session.ids[session.index]),a=session.answers[q.id],checked=session.checked[q.id],exam=session.mode==='exam';set(`<div class="quiz"><div class="row"><button onclick="pause()">← Guardar y salir</button><span class="badge">${exam?'SIMULACRO':'PRÁCTICA'} ${exam?'<span id="clock"></span>':''}</span></div><div class="track"><div class="fill" style="width:${(session.index+1)/session.ids.length*100}%"></div></div><div class="row"><span class="eyebrow">${modules[q.module]}</span><span class="subtle">${session.index+1} / ${session.ids.length}</span></div><h1 class="question">${esc(q.question)}</h1>${q.options.map((o,i)=>`<button class="option ${a===i?'selected':''} ${checked&&i===q.answer?'correct':''} ${checked&&a===i&&a!==q.answer?'wrong':''}" onclick="choose(${i})" ${checked?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join('')}${checked?`<div class="feedback ${a!==q.answer?'bad':''}"><strong>${a===q.answer?'Respuesta acertada':'Repasemos esta pregunta'}</strong><p>La solución del PDF es <b>${'ABCD'[q.answer]}. ${esc(q.options[q.answer])}</b>.</p></div>`:''}${flagged(q)&&(!exam||checked)?'<div class="notice">Revisión recomendada: esta pregunta puede contener una formulación dudosa o una referencia que haya cambiado. La corrección usa la plantilla del PDF; contrasta su aplicación actual.</div>':''}<div class="actions">${!exam&&!checked?`<button class="primary" onclick="check()" ${a===undefined?'disabled':''}>Comprobar respuesta</button>`:`<button class="primary" onclick="next()">${session.index===session.ids.length-1?'Finalizar':'Siguiente →'}</button>`}${exam&&session.index>0?'<button onclick="previous()">Anterior</button>':''}<button onclick="bookmark()">${store.bookmarks.includes(q.id)?'★ Guardada':'☆ Guardar pregunta'}</button>${exam?'<button onclick="confirmFinish()">Entregar examen</button>':''}</div><p class="subtle">${q.sources.map(s=>`Modelo ${s.model} · pregunta ${s.number}`).join(' / ')} · <a href="https://www.comunidad.madrid/docs/2026-04/ejemplo-prueba-${q.sources[0].model.toLowerCase()}.pdf" target="_blank" rel="noopener">Consultar PDF original ↗</a></p></div>`);if(exam){timer();tick=setInterval(timer,1000)}}
function choose(i){let id=session.ids[session.index];session.answers[id]=i;persist();renderQuestion()}
function record(q,a){let s=store.stats[q.id]||{tries:0,right:0};s.tries++;if(a===q.answer)s.right++;s.last=a===q.answer;store.stats[q.id]=s}
function check(){let q=Q.find(x=>x.id===session.ids[session.index]);if(session.answers[q.id]===undefined)return;session.checked[q.id]=true;record(q,session.answers[q.id]);persist();renderQuestion()}
function next(){if(session.index===session.ids.length-1){if(session.mode==='exam')confirmFinish();else finish()}else{session.index++;persist();renderQuestion()}}
function previous(){session.index--;persist();renderQuestion()}
function pause(){persist();home()}
function bookmark(){let id=session.ids[session.index];store.bookmarks=store.bookmarks.includes(id)?store.bookmarks.filter(x=>x!==id):[...store.bookmarks,id];persist();renderQuestion()}
function confirmFinish(){let unanswered=session.ids.filter(id=>session.answers[id]===undefined).length;let d=document.createElement('dialog');d.innerHTML=`<h3>¿Entregar el simulacro?</h3><p>${unanswered?`Quedan ${unanswered} preguntas sin contestar; contarán como no acertadas.`:'Has contestado todas las preguntas.'}</p><div class="actions"><button class="primary" id="submitExam">Entregar</button><button id="cancelExam">Seguir revisando</button></div>`;document.body.append(d);d.querySelector('#submitExam').onclick=()=>{d.close();d.remove();finish()};d.querySelector('#cancelExam').onclick=()=>{d.close();d.remove()};d.addEventListener('cancel',()=>d.remove());d.showModal()}
function finish(){clearInterval(tick);let s=session;if(!s)return;session=null;let qs=s.ids.map(id=>Q.find(q=>q.id===id));if(s.mode==='exam')qs.forEach(q=>record(q,s.answers[q.id]));let score=qs.filter(q=>s.answers[q.id]===q.answer).length,rows=[1,2,3,4].map(m=>({m,n:qs.filter(q=>q.module===m).length,c:qs.filter(q=>q.module===m&&s.answers[q.id]===q.answer).length})),passed=rows.every(r=>r.c>=thresholds[r.m]);if(s.mode==='exam')store.history.unshift({date:new Date().toISOString(),score,passed,rows});store.history=store.history.slice(0,30);delete store.active;save();set(`<div class="quiz"><span class="eyebrow">${s.mode==='exam'?'SIMULACRO TERMINADO':'PRÁCTICA TERMINADA'}</span><h1>${s.mode==='exam'?(passed?'Has superado el simulacro.':'Ya sabes qué repasar.'):'Cada pregunta cuenta.'}</h1><div class="bigscore">${score}<span style="font-size:25px;color:var(--muted)"> / ${qs.length}</span></div>${s.mode==='exam'?`<p>Resultado orientativo: <b>${passed?'APTO':'NO APTO'}</b>. Se exige alcanzar el mínimo en los cuatro módulos.</p>`:'<p>Repasa las soluciones y vuelve a entrenar los puntos que te cuestan.</p>'}<table><thead><tr><th>Módulo</th><th>Aciertos</th><th>${s.mode==='exam'?'Mínimo':'Estado'}</th></tr></thead><tbody>${rows.filter(r=>r.n).map(r=>`<tr><td>${modules[r.m]}</td><td>${r.c} / ${r.n}</td><td>${s.mode==='exam'?`${thresholds[r.m]} · ${r.c>=thresholds[r.m]?'Superado':'Repasar'}`:'Práctica'}</td></tr>`).join('')}</tbody></table><div class="actions"><button class="primary" onclick="home()">Volver al inicio</button><button onclick="start('errors')">Repasar errores</button></div><h2>Revisa tus respuestas</h2>${qs.map(q=>`<details class="bankitem"><summary>${s.answers[q.id]===q.answer?'✓':'✕'} ${esc(q.question)}</summary><p>Tu respuesta: ${s.answers[q.id]===undefined?'Sin contestar':esc(q.options[s.answers[q.id]])}</p><p><b>Solución del PDF: ${'ABCD'[q.answer]}. ${esc(q.options[q.answer])}</b></p>${flagged(q)?'<p>Revisión recomendada: contrasta esta pregunta con la normativa o información actual.</p>':''}<p class="subtle">Modelo ${q.sources[0].model}, pregunta ${q.sources[0].number}</p></details>`).join('')}</div>`)}
function bank(){clearInterval(tick);set(`<span class="eyebrow">BIBLIOTECA DE PREGUNTAS</span><h1>Explora. Entiende. Repasa.</h1><p>${Q.length} preguntas únicas extraídas de 240 preguntas en cuatro modelos. Las coincidencias exactas se agrupan conservando su procedencia.</p><div class="actions"><input id="search" type="search" placeholder="Buscar una pregunta…" aria-label="Buscar pregunta"><select id="filter" aria-label="Filtrar módulo"><option value="0">Todos los módulos</option>${modules.slice(1).map((m,i)=>`<option value="${i+1}">${m}</option>`).join('')}</select></div><div id="items"></div>`);$('search').oninput=filterBank;$('filter').onchange=filterBank;filterBank()}
function filterBank(){let text=$('search').value.toLocaleLowerCase('es'),mod=Number($('filter').value),pool=Q.filter(q=>(!mod||q.module===mod)&&q.question.toLocaleLowerCase('es').includes(text));$('items').innerHTML=`<p class="subtle">${pool.length} resultados</p>`+pool.map(q=>`<details class="bankitem"><summary>${esc(q.question)}</summary>${q.options.map((o,i)=>`<p>${'ABCD'[i]}. ${esc(o)}</p>`).join('')}<p><b>Solución del PDF: ${'ABCD'[q.answer]}</b></p>${flagged(q)?'<div class="notice">Revisión recomendada: puede contener una errata o información que haya cambiado.</div>':''}<p class="subtle">${q.sources.map(s=>`Modelo ${s.model} · pregunta ${s.number}`).join(' / ')}</p></details>`).join('')}
function sources(){clearInterval(tick);set(`<span class="eyebrow">PROCEDENCIA Y LÍMITES</span><h1>Practicar con una fuente clara.</h1><div class="panel"><h2>Los cuatro modelos oficiales</h2><p>Banco extraído el 15 de octubre de 2026: 240 preguntas, 234 tras agrupar coincidencias exactas. Se conservan el texto, las opciones y la solución que indica cada PDF. No se han inventado explicaciones jurídicas ni sanitarias.</p>${['i','ii','iii','iv'].map(x=>`<p><a href="https://www.comunidad.madrid/docs/2026-04/ejemplo-prueba-${x}.pdf" target="_blank" rel="noopener">Abrir modelo oficial ${x.toUpperCase()} ↗</a></p>`).join('')}<p><a href="https://www.comunidad.madrid/transporte/pruebas-conductor-vtc" target="_blank" rel="noopener">Información y materiales de la Comunidad de Madrid ↗</a></p><p><a href="https://www.bocm.es/bocm-20250401-34" target="_blank" rel="noopener">Orden reguladora y contenido de la prueba ↗</a></p></div><div class="notice"><b>Los ejemplos no garantizan las preguntas del examen.</b> Algunos enunciados y soluciones pueden tener erratas, ambigüedades o referencias antiguas. Se señalan preventivamente preguntas sensibles a revisión; esta marca no es una auditoría exhaustiva. La app reproduce la plantilla del PDF, no certifica su vigencia.</div><h2>Cómo funciona el simulacro</h2><p>Selecciona aleatoriamente 12 preguntas de castellano, 18 de medio físico, 18 de accesibilidad y 12 de normativa. Dispone de 60 minutos. Las preguntas sin responder cuentan como no acertadas. Para el resultado orientativo «apto» hay que acertar al menos 6, 9, 9 y 6 respectivamente.</p><h2>Tu progreso</h2><p>Se guarda en este navegador, sin sincronización entre dispositivos. Borrar los datos del navegador elimina el historial. Puedes pausar una sesión; el tiempo del simulacro sigue corriendo al salir.</p><button onclick="resetProgress()">Borrar mi progreso</button>`)}
function history(){clearInterval(tick);set(`<span class="eyebrow">TU EVOLUCIÓN</span><h1>Mis simulacros</h1>${store.history.length?store.history.map(x=>`<article class="card" style="margin-bottom:14px"><div class="row"><strong>${x.score} / 60 · ${x.passed?'APTO':'NO APTO'}</strong><span>${new Date(x.date).toLocaleString('es-ES')}</span></div></article>`).join(''):'<p>Todavía no has completado ningún simulacro.</p>'}<button onclick="home()">Volver al inicio</button>`)}
function resetProgress(){if(confirm('¿Borrar todo el progreso, las preguntas guardadas y la sesión pendiente?')){store={stats:{},bookmarks:[],history:[]};save();home()}}
fetch('questions.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(q=>{Q=q;home()}).catch(()=>set('<h1>No se pudo cargar el banco de preguntas.</h1><p>Recarga la página para volver a intentarlo.</p>'));
